<?php
declare(strict_types=1);
namespace App\Services;
use App\Config\Database;
use App\Support\Reference;
use PDO;
use RuntimeException;

final class OfferService
{
 private static function requireOperations(string $p):void{if(!Auth::hasRole('MCCOLLIN_OPERATIONS')||!Auth::can($p))throw new RuntimeException('Operations offer permission is required.');}
 private static function operationsRoleId():int{foreach(Auth::context()['roles']??[] as$r)if($r['role_code']==='MCCOLLIN_OPERATIONS')return(int)$r['user_role_id'];throw new RuntimeException('Operations role is required.');}
 private static function carrierContext():array{if(!Auth::hasRole('TRUCK_OWNER'))throw new RuntimeException('Carrier role is required.');$uid=(int)Auth::user()['id'];$p=CarrierOnboarding::current($uid);if(!$p||$p['verification_status']!=='verified'||$p['case_status']!=='approved')throw new RuntimeException('Verified Carrier access is required.');return['user_id'=>$uid,'company_id'=>$p['owner_type']==='company'?(int)$p['subject_id']:null,'carrier_user_id'=>$p['owner_type']==='individual'?$uid:null];}
 public static function fxRate():float{$r=Database::connection()->query("SELECT decimal_value FROM configuration_setting_versions WHERE setting_code='FX_TZS_PER_USD' AND status='active' AND effective_from<=UTC_TIMESTAMP(6) AND (effective_to IS NULL OR effective_to>UTC_TIMESTAMP(6)) ORDER BY version_no DESC LIMIT 1")->fetchColumn();if(!$r||(float)$r<=0)throw new RuntimeException('Active TZS/USD configuration is missing.');return(float)$r;}
 private static function amount(mixed$v):float{$n=(float)str_replace([',',' '],'',(string)$v);if($n<=0||$n>99999999999999999)throw new RuntimeException('Offer amount must be a positive value.');return round($n,2);}
 private static function pricing(mixed$value,string$currency,float$fx):array{$currency=strtoupper(trim($currency));if(!in_array($currency,['TZS','USD'],true))throw new RuntimeException('Choose TZS or USD.');$entered=self::amount($value);$tzs=$currency==='TZS'?$entered:round($entered*$fx,2);$usd=$currency==='USD'?$entered:round($entered/$fx,2);return['currency'=>$currency,'entered'=>$entered,'tzs'=>$tzs,'usd'=>$usd];}
 private static function breakdown(array$parts,string$currency):string{$labels=['total_cost'=>'Transport cost','company_charges'=>'Company charges','insurance'=>'Insurance','taxes'=>'Taxes'];$lines=[];foreach($labels as$key=>$label){$raw=trim((string)($parts[$key]??''));if($raw==='')continue;$value=(float)str_replace([',',' '],'',$raw);if($value<0||$value>99999999999999999)throw new RuntimeException($label.' must be zero or a positive amount.');$lines[]=$label.': '.$currency.' '.number_format($value,2,'.',',');}return implode("\n",$lines);}
 public static function expireDue(?int$userId=null):int{$pdo=Database::connection();$pdo->beginTransaction();try{$rows=$pdo->query("SELECT offer_id FROM bids_offers WHERE offer_status='sent' AND status='active' AND expires_at<=UTC_TIMESTAMP(6) FOR UPDATE")->fetchAll();foreach($rows as$r){$id=(int)$r['offer_id'];$pdo->prepare("UPDATE bids_offers SET offer_status='expired',updated_by_user_id=?,row_version=row_version+1 WHERE offer_id=? AND offer_status='sent'")->execute([$userId,$id]);self::history($pdo,$id,'sent','expired',$userId,null,'Offer expired after 24 hours');self::audit($pdo,'OFFER_EXPIRED',$id,$userId,[]);} $pdo->commit();return count($rows);}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function createForMatches(int$loadId,array$items,int$userId):int
 {
  self::requireOperations('OFFER_CREATE');if($userId!==(int)Auth::user()['id'])throw new RuntimeException('Invalid Operations actor.');if(!$items)throw new RuntimeException('Select at least one candidate.');$fx=self::fxRate();$pdo=Database::connection();$pdo->beginTransaction();try{$created=0;foreach($items as$item){$matchId=(int)($item['match_id']??0);$pricing=self::pricing($item['amount']??0,(string)($item['currency']??'TZS'),$fx);$amount=$pricing['tzs'];$usd=$pricing['usd'];$breakdown=self::breakdown((array)($item['breakdown']??[]),$pricing['currency']);if(strlen($breakdown)>2000)throw new RuntimeException('Price explanation cannot exceed 2000 characters.');$sql="SELECT m.*,ea.carrier_company_id,ea.carrier_user_id,ra.availability_status FROM matches m JOIN eligibility_assessments ea ON ea.eligibility_assessment_id=m.eligibility_assessment_id JOIN resource_availability ra ON ra.truck_id=m.truck_id AND ra.driver_id=m.driver_id WHERE m.match_id=? AND m.load_id=? AND m.status='active' AND m.suitability_status<>'unsuitable' FOR UPDATE";$st=$pdo->prepare($sql);$st->execute([$matchId,$loadId]);$m=$st->fetch();if(!$m||$m['availability_status']!=='available')throw new RuntimeException('Every selected candidate must still be active and available.');$st=$pdo->prepare("SELECT COUNT(*) FROM bids_offers WHERE match_id=? AND offer_status IN('sent','countered','accepted') AND status='active'");$st->execute([$matchId]);if((int)$st->fetchColumn()>0)throw new RuntimeException('A selected candidate already has an open offer.');$thread=Reference::make('OFT');$ref=Reference::make('OFV');$pdo->prepare("INSERT INTO bids_offers(offer_ref,offer_thread_ref,version_no,match_id,load_id,load_version_id,truck_id,driver_id,carrier_company_id,carrier_user_id,offered_amount_tzs,fx_tzs_per_usd,offered_amount_usd,price_breakdown,offer_status,sent_at,expires_at,sent_by_user_id,metadata_json,status,created_by_user_id,updated_by_user_id) VALUES(?,?,1,?,?,?,?,?,?,?,?,?,?,?,'sent',UTC_TIMESTAMP(6),DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 24 HOUR),?,?,'active',?,?)")->execute([$ref,$thread,$m['match_id'],$m['load_id'],$m['load_version_id'],$m['truck_id'],$m['driver_id'],$m['carrier_company_id'],$m['carrier_user_id'],$amount,$fx,$usd,$breakdown!==''?$breakdown:null,$userId,json_encode(['pricing'=>'operations_fixed','entered_currency'=>$pricing['currency'],'entered_amount'=>$pricing['entered']],JSON_THROW_ON_ERROR),$userId,$userId]);$id=(int)$pdo->lastInsertId();self::history($pdo,$id,null,'sent',$userId,self::operationsRoleId(),'Operations sent 24-hour transport offer');self::audit($pdo,'OFFER_SENT',$id,$userId,['load_id'=>$loadId,'match_id'=>$matchId,'amount_tzs'=>$amount,'amount_usd'=>$usd]);$created++;} $pdo->commit();return$created;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
 }
 public static function operationsQueue():array{self::requireOperations('OFFER_QUEUE_VIEW');self::expireDue((int)Auth::user()['id']);$sql="SELECT o.*,l.load_ref,t.registration_number,du.display_name driver_name,cc.display_name carrier_company_name,cu.display_name carrier_user_name FROM bids_offers o JOIN loads l ON l.load_id=o.load_id JOIN trucks t ON t.truck_id=o.truck_id JOIN drivers d ON d.driver_id=o.driver_id JOIN users du ON du.user_id=d.user_id LEFT JOIN companies cc ON cc.company_id=o.carrier_company_id LEFT JOIN users cu ON cu.user_id=o.carrier_user_id WHERE o.status='active' ORDER BY FIELD(o.offer_status,'countered','accepted','sent','declined','expired','closed','revised'),o.updated_at DESC";return Database::connection()->query($sql)->fetchAll();}
 public static function operationsFind(int$id):?array{self::requireOperations('OFFER_QUEUE_VIEW');$st=Database::connection()->prepare(self::detailSql()." WHERE o.offer_id=? LIMIT 1");$st->execute([$id]);$r=$st->fetch();return$r?:null;}
 public static function revise(int$id,mixed$value,string$currency,array$parts,int$userId):int
 {self::requireOperations('OFFER_REVISE');if($userId!==(int)Auth::user()['id'])throw new RuntimeException('Invalid Operations actor.');$fx=self::fxRate();$pricing=self::pricing($value,$currency,$fx);$amount=$pricing['tzs'];$usd=$pricing['usd'];$breakdown=self::breakdown($parts,$pricing['currency']);if(strlen($breakdown)>2000)throw new RuntimeException('Price explanation cannot exceed 2000 characters.');$pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT * FROM bids_offers WHERE offer_id=? AND status='active' FOR UPDATE");$st->execute([$id]);$o=$st->fetch();if(!$o||$o['offer_status']!=='countered')throw new RuntimeException('Only a countered offer may be revised.');$st=$pdo->prepare("SELECT availability_status FROM resource_availability WHERE truck_id=? AND driver_id=? FOR UPDATE");$st->execute([$o['truck_id'],$o['driver_id']]);if($st->fetchColumn()!=='available')throw new RuntimeException('The candidate is no longer available.');$pdo->prepare("UPDATE bids_offers SET offer_status='revised',updated_by_user_id=?,row_version=row_version+1 WHERE offer_id=? AND offer_status='countered'")->execute([$userId,$id]);$ref=Reference::make('OFV');$pdo->prepare("INSERT INTO bids_offers(offer_ref,offer_thread_ref,version_no,parent_offer_id,match_id,load_id,load_version_id,truck_id,driver_id,carrier_company_id,carrier_user_id,offered_amount_tzs,fx_tzs_per_usd,offered_amount_usd,price_breakdown,offer_status,sent_at,expires_at,sent_by_user_id,metadata_json,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'sent',UTC_TIMESTAMP(6),DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 24 HOUR),?,?,'active',?,?)")->execute([$ref,$o['offer_thread_ref'],(int)$o['version_no']+1,$id,$o['match_id'],$o['load_id'],$o['load_version_id'],$o['truck_id'],$o['driver_id'],$o['carrier_company_id'],$o['carrier_user_id'],$amount,$fx,$usd,$breakdown!==''?$breakdown:null,$userId,json_encode(['revised_after_counter'=>true,'entered_currency'=>$pricing['currency'],'entered_amount'=>$pricing['entered']],JSON_THROW_ON_ERROR),$userId,$userId]);$newId=(int)$pdo->lastInsertId();self::history($pdo,$id,'countered','revised',$userId,self::operationsRoleId(),'Operations issued a revised offer');self::history($pdo,$newId,null,'sent',$userId,self::operationsRoleId(),'Revised 24-hour offer sent');self::audit($pdo,'OFFER_REVISED',$newId,$userId,['parent_offer_id'=>$id,'amount_tzs'=>$amount]);$pdo->commit();return$newId;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function ownQueue():array{$c=self::carrierContext();if(!Auth::can('OFFER_VIEW_OWN'))throw new RuntimeException('Offer view permission is required.');self::expireDue($c['user_id']);$col=$c['company_id']?'o.carrier_company_id':'o.carrier_user_id';$val=$c['company_id']?:$c['carrier_user_id'];$st=Database::connection()->prepare("SELECT o.*,l.load_ref,l.cargo_summary,t.registration_number FROM bids_offers o JOIN loads l ON l.load_id=o.load_id JOIN trucks t ON t.truck_id=o.truck_id WHERE {$col}=? AND o.status='active' ORDER BY o.updated_at DESC");$st->execute([$val]);return$st->fetchAll();}
 public static function ownFind(int$id):?array{$c=self::carrierContext();if(!Auth::can('OFFER_VIEW_OWN'))return null;$col=$c['company_id']?'o.carrier_company_id':'o.carrier_user_id';$val=$c['company_id']?:$c['carrier_user_id'];$st=Database::connection()->prepare(self::detailSql()." WHERE o.offer_id=? AND {$col}=? LIMIT 1");$st->execute([$id,$val]);$r=$st->fetch();return$r?:null;}
 public static function respond(int$id,string$action,?float$counter,string$note,int$userId):void
 {if(!Auth::can('OFFER_RESPOND_OWN'))throw new RuntimeException('Offer response permission is required.');$c=self::carrierContext();if($userId!==$c['user_id'])throw new RuntimeException('Invalid Carrier actor.');if(!in_array($action,['accept','decline','counter'],true))throw new RuntimeException('Invalid offer response.');$note=trim($note);if(strlen($note)>2000)throw new RuntimeException('Response note cannot exceed 2000 characters.');$pdo=Database::connection();$pdo->beginTransaction();try{$col=$c['company_id']?'o.carrier_company_id':'o.carrier_user_id';$val=$c['company_id']?:$c['carrier_user_id'];$st=$pdo->prepare("SELECT o.* FROM bids_offers o WHERE o.offer_id=? AND {$col}=? AND o.status='active' FOR UPDATE");$st->execute([$id,$val]);$o=$st->fetch();if(!$o||$o['offer_status']!=='sent'||strtotime((string)$o['expires_at'])<=time())throw new RuntimeException('Only a current sent offer may be answered.');if($action==='decline'){$pdo->prepare("UPDATE bids_offers SET offer_status='declined',response_note=?,responded_at=UTC_TIMESTAMP(6),responded_by_user_id=?,updated_by_user_id=?,row_version=row_version+1 WHERE offer_id=? AND offer_status='sent'")->execute([$note!==''?$note:null,$userId,$userId,$id]);self::history($pdo,$id,'sent','declined',$userId,null,'Carrier declined offer');self::audit($pdo,'OFFER_DECLINED',$id,$userId,[]);}elseif($action==='counter'){$amount=self::amount($counter);$usd=round($amount/(float)$o['fx_tzs_per_usd'],2);$pdo->prepare("UPDATE bids_offers SET offer_status='countered',counter_amount_tzs=?,counter_amount_usd=?,response_note=?,responded_at=UTC_TIMESTAMP(6),responded_by_user_id=?,updated_by_user_id=?,row_version=row_version+1 WHERE offer_id=? AND offer_status='sent'")->execute([$amount,$usd,$note!==''?$note:null,$userId,$userId,$id]);self::history($pdo,$id,'sent','countered',$userId,null,'Carrier submitted counteroffer');self::audit($pdo,'OFFER_COUNTERED',$id,$userId,['counter_amount_tzs'=>$amount,'counter_amount_usd'=>$usd]);}else{$st=$pdo->prepare("SELECT availability_status FROM resource_availability WHERE truck_id=? AND driver_id=? FOR UPDATE");$st->execute([$o['truck_id'],$o['driver_id']]);if($st->fetchColumn()!=='available')throw new RuntimeException('This Driver–truck pair is no longer available.');$st=$pdo->prepare("SELECT offer_id FROM bids_offers WHERE load_id=? AND offer_status='accepted' AND status='active' LIMIT 1 FOR UPDATE");$st->execute([$o['load_id']]);if($st->fetchColumn())throw new RuntimeException('Another Carrier already accepted this load offer.');$pdo->prepare("UPDATE bids_offers SET offer_status='accepted',response_note=?,responded_at=UTC_TIMESTAMP(6),responded_by_user_id=?,reserved_at=UTC_TIMESTAMP(6),updated_by_user_id=?,row_version=row_version+1 WHERE offer_id=? AND offer_status='sent'")->execute([$note!==''?$note:null,$userId,$userId,$id]);$st=$pdo->prepare("SELECT offer_id,offer_status FROM bids_offers WHERE (load_id=? OR (truck_id=? AND driver_id=?)) AND offer_id<>? AND offer_status IN('sent','countered') AND status='active' FOR UPDATE");$st->execute([$o['load_id'],$o['truck_id'],$o['driver_id'],$id]);$closed=$st->fetchAll();$pdo->prepare("UPDATE bids_offers SET offer_status='closed',updated_by_user_id=?,row_version=row_version+1 WHERE (load_id=? OR (truck_id=? AND driver_id=?)) AND offer_id<>? AND offer_status IN('sent','countered') AND status='active'")->execute([$userId,$o['load_id'],$o['truck_id'],$o['driver_id'],$id]);foreach($closed as$closedOffer){self::history($pdo,(int)$closedOffer['offer_id'],$closedOffer['offer_status'],'closed',$userId,null,'Closed after first valid competing acceptance');}$st=$pdo->prepare("UPDATE resource_availability SET availability_status='reserved',reason=?,updated_by_user_id=?,row_version=row_version+1 WHERE truck_id=? AND driver_id=? AND availability_status='available'");$st->execute(['Reserved by accepted offer '.$o['offer_ref'],$userId,$o['truck_id'],$o['driver_id']]);if($st->rowCount()!==1)throw new RuntimeException('Resource reservation changed.');$st=$pdo->prepare("UPDATE trucks SET availability_status='reserved',updated_by_user_id=?,row_version=row_version+1 WHERE truck_id=? AND availability_status='available'");$st->execute([$userId,$o['truck_id']]);if($st->rowCount()!==1)throw new RuntimeException('Truck reservation changed.');$st=$pdo->prepare("UPDATE drivers SET availability_status='reserved',updated_by_user_id=?,row_version=row_version+1 WHERE driver_id=? AND availability_status='available'");$st->execute([$userId,$o['driver_id']]);if($st->rowCount()!==1)throw new RuntimeException('Driver reservation changed.');self::history($pdo,$id,'sent','accepted',$userId,null,'First valid Carrier acceptance; resources reserved pending Phase 7C assignment');self::audit($pdo,'OFFER_ACCEPTED_AND_RESERVED',$id,$userId,['load_id'=>(int)$o['load_id'],'truck_id'=>(int)$o['truck_id'],'driver_id'=>(int)$o['driver_id']]);}$pdo->commit();}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 private static function detailSql():string{return"SELECT o.*,l.load_ref,l.cargo_summary,oa.city origin_city,da.city destination_city,t.registration_number,t.make_name,t.model_name,t.capacity_value,t.capacity_unit,du.display_name driver_name,cc.display_name carrier_company_name,cu.display_name carrier_user_name FROM bids_offers o JOIN loads l ON l.load_id=o.load_id JOIN addresses oa ON oa.address_id=l.origin_address_id JOIN addresses da ON da.address_id=l.destination_address_id JOIN trucks t ON t.truck_id=o.truck_id JOIN drivers d ON d.driver_id=o.driver_id JOIN users du ON du.user_id=d.user_id LEFT JOIN companies cc ON cc.company_id=o.carrier_company_id LEFT JOIN users cu ON cu.user_id=o.carrier_user_id";}
 private static function history(PDO$pdo,int$id,?string$old,string$new,?int$uid,?int$roleId,string$reason):void{$pdo->prepare("INSERT INTO status_history(status_history_ref,entity_type,entity_id_value,previous_status,new_status,actor_user_id,actor_user_role_id,source_channel,reason,occurred_at,status,created_by_user_id) VALUES(?,'transport_offer',?,?,?,?,?,'web',?,UTC_TIMESTAMP(6),'active',?)")->execute([Reference::make('STH'),$id,$old,$new,$uid,$roleId,$reason,$uid]);}
 private static function audit(PDO$pdo,string$action,int$id,?int$uid,array$extra):void{$meta=json_encode(array_merge(['action_code'=>$action,'entity_type'=>'transport_offer','entity_id'=>$id,'source'=>'web'],$extra),JSON_THROW_ON_ERROR);$pdo->prepare("INSERT INTO audit_events(audit_event_ref,metadata_json,status,created_by_user_id) VALUES(?,?,'active',?)")->execute([Reference::make('AUD'),$meta,$uid]);}
}
